pub fn rollback_count(applied: &[AppliedRecord], live_keys: &[String]) -> u64 {
    // Deduplicate by mem_key; only the latest applied_at_ms is kept
    let mut latest: HashMap<&str, &AppliedRecord> = HashMap::new();
    for r in applied {
        match latest.get(r.mem_key.as_str()) {
            Some(prev) if prev.applied_at_ms >= r.applied_at_ms => {}
            _ => { latest.insert(r.mem_key.as_str(), r); }
        }
    }
    let live: HashSet<&str> = live_keys.iter().map(|k| k.as_str()).collect();
    latest.values().filter(|r| !live.contains(r.mem_key.as_str())).count() as u64
}

